#include "stdafx.h"#include "ControlBuilderApp.h"#include "PrjView.h"#include "ControlBuilderH5xxDebug.h"#include <macros/AutoRestore.h>// KPrjViewIMPLEMENT_DYNCREATE(KPrjView, CTreeView)KPrjView::KPrjView(): m_pCtrl( NULL ), m_bInited( false ), m_itemFirstSelect( NULL ){}KPrjView::~KPrjView(){}KControlBuilderDoc* KPrjView::GetDocument(){  ASSERT(m_pDocument->IsKindOf(RUNTIME_CLASS(KControlBuilderDoc)));  return (KControlBuilderDoc*)m_pDocument;}BEGIN_MESSAGE_MAP(KPrjView, CTreeView)  ON_MESSAGE( WM_USER, OnWmUser)  ON_NOTIFY_REFLECT(NM_DBLCLK, &KPrjView::OnNMDblclk)  ON_NOTIFY_REFLECT(NM_RCLICK, &KPrjView::OnNMRclick)END_MESSAGE_MAP()// KPrjView diagnostics#ifdef _DEBUGvoid KPrjView::AssertValid() const{	CTreeView::AssertValid();}#ifndef _WIN32_WCEvoid KPrjView::Dump(CDumpContext& dc) const{	CTreeView::Dump(dc);}#endif#endif //_DEBUG// KPrjView message handlersBOOL KPrjView::Create(LPCTSTR lpszClassName, LPCTSTR lpszWindowName, DWORD dwStyle, const RECT& rect, CWnd* pParentWnd, UINT nID, CCreateContext* pContext){  dwStyle |= TVS_HASBUTTONS | TVS_HASLINES | TVS_LINESATROOT | TVS_SHOWSELALWAYS | TVS_TRACKSELECT | WS_TABSTOP;    BOOL b = CTreeView::Create(lpszClassName, lpszWindowName, dwStyle, rect, pParentWnd, nID, pContext);  m_pCtrl = &GetTreeCtrl();  m_imgList.Create(IDB_BITMAP1, 20, 0, RGB(166,202,240));  m_pCtrl->SetImageList(&m_imgList,TVSIL_NORMAL);  return b;}LRESULT KPrjView::OnWmUser( WPARAM wParam, LPARAM lParam ){  if( !m_bInited )  {    m_bInited = true;    SH_Module * entryModule = GetDocument()->m_entryModule;    if( !entryModule )      return 0L;    LPCSTR pszSelect = GetDocument()->m_szFirstSelect;    FillTree( TVI_ROOT, entryModule, 1, *pszSelect ? pszSelect : NULL );    GetDocument()->m_szFirstSelect.Empty();    if( m_itemFirstSelect )    {      m_pCtrl->SelectItem( m_itemFirstSelect );      ShowItem( m_itemFirstSelect );      m_itemFirstSelect = NULL;    }  }  if( wParam && lParam )  {    LPCSTR pszBlkName = (LPCSTR)lParam;    size_t l = strlen( pszBlkName );    if( l < _countof(GetDocument()->m_entryModule->BlockName) )    {      tNamedTree_::iterator it = m_FindNamedItem.find( pszBlkName );      if( m_FindNamedItem.end() != it )      {        m_pCtrl->SelectItem( it->second );      }    }  }  return 1L;}void KPrjView::FillTree( HTREEITEM parent, SH_Module *module, int level, LPCSTR pszSelect ){  int img = GetImageIndex( parent, module );  LPCSTR pPnt = strchr( module->BlockName, '.' );  const size_t lenModule = strlen( module->BlockName );  if( pPnt )    ++pPnt;  else    pPnt = module->BlockName;  HTREEITEM hCurRoot = m_pCtrl->InsertItem( pPnt, img, img, parent );  m_FindNamedItem[module->BlockName] = hCurRoot;  if( pszSelect && *pszSelect && !m_itemFirstSelect )  {    if( !_stricmp(module->BlockName, pszSelect) )      m_itemFirstSelect = hCurRoot;  }  if( module->szFile[0] )    m_pCtrl->SetItemData( hCurRoot, (DWORD_PTR)module->szFile );  for( size_t i=0; i < module->nSubModules; ++i )  {    FillTree( hCurRoot, module->ppSubModules[i], level+1, pszSelect );  }  for( size_t i=0; i < module->nBlocks; ++i )  {    img = GetImageIndex( parent, module->ppBlocks[i] );    pPnt = strchr( module->ppBlocks[i]->BlockName, '.' );    if( pPnt )    {      const size_t lenBlock = pPnt - module->ppBlocks[i]->BlockName;      if( lenBlock!=lenModule )        ++pPnt;      else      {        if( !_strnicmp(module->ppBlocks[i]->BlockName, module->BlockName, lenModule ))          ++pPnt;        else          pPnt = module->ppBlocks[i]->BlockName;      }    }    else      pPnt = module->ppBlocks[i]->BlockName;    HTREEITEM hItem = m_pCtrl->InsertItem( pPnt, img, img, hCurRoot );  }  if( level < 3 )    m_pCtrl->Expand( hCurRoot, TVE_EXPAND );}int KPrjView::GetImageIndex( HTREEITEM item, KBmBase *type ){  switch( type->H_Type )  {  case id_PCDIFLAGARRCH:  case id_PCDINUMARRCH:    return 56;  case id_PCDI_MASTER:    return 15;  case id_CEEC300:    return 50;  case id_IOLINK:    return 96;  case id_FTEB:  case id_CONTROLMODULE:    return 0;  case id_xHART_HL:    return 21;  case id_Dx_24y:    return 22;  case id_xC300:    return 60;  case id_DICHANNEL:  case id_AICHANNEL:  case id_HAICHANNEL:    return 58;  case id_DOCHANNEL:  case id_AOCHANNEL:    return 57;  case id_NOT:    return 56;  case id_TEXTCOMMENT:  default:    //if( type->H_Type>=id_AUXCALC && type->H_Type<=id_DIV )      return 56;    ASSERT(0);  }  return 50;}void KPrjView::OnNMDblclk(NMHDR *pNMHDR, LRESULT *pResult){  *pResult = 0;  HTREEITEM hItem = m_pCtrl->GetSelectedItem();  if ( hItem == NULL )      return;  ShowItem( hItem );}static bool s_bInShow = false;void KPrjView::ShowItem( HTREEITEM hItem ){  if( s_bInShow )    return;  LPCSTR szFile = (LPCSTR)m_pCtrl->GetItemData(hItem);  TAutoRestore<bool> ar(s_bInShow);  s_bInShow = true;  if( szFile )  {    CString blkName = m_pCtrl->GetItemText( hItem );    GetDocument()->OnSelectCnf( szFile, blkName );  }  else  {    CString name = m_pCtrl->GetItemText( hItem );    HTREEITEM hParent = m_pCtrl->GetParentItem( hItem );    if( NULL==hParent )      return;    CString parentName = m_pCtrl->GetItemText( hParent );    parentName += ".";    parentName += name;    GetDocument()->m_pcb->ShowACSObject( *GetParentFrame(), (char*)(LPCSTR)parentName, NULL, true );  }}void KPrjView::OnNMRclick(NMHDR *pNMHDR, LRESULT *pResult){  *pResult = 0;  HTREEITEM hItem = m_pCtrl->GetSelectedItem();  if ( hItem == NULL )      return;  LPCSTR szFile = (LPCSTR)m_pCtrl->GetItemData(hItem);  TAutoRestore<bool> ar(s_bInShow);  s_bInShow = true;  if( szFile )  {    CString blkName = m_pCtrl->GetItemText( hItem );    GetDocument()->OnSelectCnf( szFile, blkName );    GetDocument()->m_pcb->ShowACSObject( *GetParentFrame(), (char*)(LPCSTR)blkName, NULL, true );  }}